def init_worker():
    signal.signal(signal.SIGINT, signal.SIG_IGN)

def redirs(urlnya):
    try:
        openquery = open('openredir/query.txt', 'r').read().split()
        for querynya in openquery:
            if 'http' in urlnya[0:4]:
                if querynya + '=' in urlnya:
                    get = urlnya.split('?')[1]
                    get = get.split(querynya + '=')[1]
                    if '&' in get:
                        get = get[1:].split('&')[0]
                    openplayloads = open('openredir/playload.txt', 'r').read().split()
                    for playloadnya in openplayloads:
                        replace = urlnya.replace(get, playloadnya)
                        response = requests.get(replace, allow_redirects=True)
                        if 'Example Domain' in response.text:
                            if replace in open('result_open.txt', 'r').read():
                                pass
                            else:
                                halo = replace + '\n'
                                print(Fore.GREEN + '[+] ' + Fore.CYAN + querynya.upper() + Fore.WHITE + ' => ' + Fore.WHITE + replace)
                                save = open('result_open.txt', 'a+')
                                save.write(halo)
                                save.close()
                        else:
                            print(Fore.YELLOW + '[-] ' + Fore.WHITE + replace)
                else:
                    print(Fore.RED + '[-] ' + Fore.YELLOW + querynya.upper() + Fore.CYAN + ' => ' + Fore.WHITE + urlnya)
            else:
                print(Fore.RED + '[x] ' + Fore.YELLOW + urlnya)
    except Exception:
        return False

def dorkgens(number):
    try:
        openkeyword = open('dorkgen/keyword.txt', 'r').read().splitlines()
        opensite = open('dorkgen/site.txt', 'r').read().split()
        openparam = open('dorkgen/param.txt', 'r').read().split()
        openplayload = open('dorkgen/query.txt', 'r').read().split()
        
        keywords = []
        sites = []
        params = []
        playloads = []
        
        for site in opensite:
            sites.append(site)
        for param in openparam:
            params.append(param)
        for playload in openplayload:
            playloads.append(playload)
            
        for keyword in openkeyword:
            for _ in range(number):
                dork = random.choice(params) + keyword + ' inurl:' + random.choice(playloads) + '= site:' + random.choice(sites)
                print(Fore.GREEN + '[+] ' + Fore.WHITE + dork)
                halo = dork + '\n'
                save = open('dorks.txt', 'a+')
                save.write(halo)
                save.close()
    except Exception:
        return False

